  function printSVG(p){const s=viewBounds(surface,activePart,0),w=p.width+p.bleed*2,h=p.height+p.bleed*2;return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}mm" height="${h}mm" viewBox="0 0 ${w} ${h}"><metadata>${esc(JSON.stringify({surface,part:activePart,widthMm:p.width,heightMm:p.height,bleedMm:p.bleed,calibrated:true,colorSpace:'RGB',type:'projected-artwork-not-cutting-template'}))}</metadata><defs><clipPath id="trim"><rect x="0" y="0" width="${w}" height="${h}"/></clipPath></defs><g clip-path="url(#trim)">${p.includeBase?`<rect width="${w}" height="${h}" fill="${esc(currentBase())}"/>`:""}<g transform="translate(${p.bleed} ${p.bleed}) scale(${p.width/s.w} ${p.height/s.h}) translate(${-s.x} ${-s.y})">${svgPanel(surface,p.includeBase,activePart)}</g></g></svg>`;}
  async function printRaster(p){
    const limit=settings.quality==='low'?24000000:48000000;
    if(p.pixelW>16000||p.pixelH>16000||p.pixelW*p.pixelH>limit)throw Error('此尺寸的位图超过当前画质的内存预算，请使用 SVG，或降低 DPI / 分幅导出');
    const originals=new Map(),preview=images;
    try{
      for(const l of visibleLayers()){if(l.type==='image'&&l.visible&&!originals.has(l.asset)){const im=new Image();im.src=project.assets[l.asset].src;await im.decode();originals.set(l.asset,im);}}
      images=new Map([...preview,...originals]);
      const c=document.createElement('canvas');c.width=p.pixelW;c.height=p.pixelH;const x=c.getContext('2d');
      if(p.includeBase){x.fillStyle=currentBase();x.fillRect(0,0,c.width,c.height);}
      x.scale(p.pixelW/(p.width+2*p.bleed),p.pixelH/(p.height+2*p.bleed));x.translate(p.bleed,p.bleed);const b=viewBounds(surface,activePart,0);x.scale(p.width/b.w,p.height/b.h);x.translate(-b.x,-b.y);paint(x,surface,p.includeBase,activePart);
      const result=c.toDataURL('image/png');c.width=c.height=1;return result;
    }finally{images=preview;for(const im of originals.values())im.src='';}
  }
  document.querySelectorAll('[data-export]').forEach(b=>b.onclick=run(async()=>{b.disabled=true;try{const kind=b.dataset.export;if(kind==='texture')await exportFile(filename('贴图.png'),createPanel(surface,true,activePart).toDataURL(),true);else if(kind==='svg')await exportFile(filename('设计.svg'),designSVG(surface,activePart));else if(kind==='project'){await save(true);await exportFile(project.name+'.su7design',JSON.stringify(portableProject()));}else{const p=printSettings();remember();Object.assign(productionPanel(),{widthMm:p.width,heightMm:p.height,calibrated:true});changed();const ext=kind.split('-')[1];if(ext==='svg')await exportFile(filename('制作.svg'),printSVG(p));else await exportFile(filename('制作.'+ext),await printRaster(p),true,{print:{dpi:p.dpi,widthMm:p.width+2*p.bleed,heightMm:p.height+2*p.bleed}});}}finally{b.disabled=false;}}));
  $('export-all').onclick=run(async()=>{const files=[];for(const r of Object.keys(surfaces)){files.push({name:r+'-color.png',data:createPanel(r).toDataURL(),base64:true},{name:r+'-editable.svg',data:designSVG(r)},{name:r+'-projection-guide.svg',data:guideSVG(r)});}files.push({name:'projection.json',data:JSON.stringify({regions:['left','right','top','front','rear'],atlas:{width:3072,height:2048,columns:3,tile:1024},panels:surfaces,note:'模型投影；实际尺寸需校准，非裁切刀模'},null,2)});const d=await api('export',{name:project.name+'_全部车面.zip',files});$('export-status').textContent='已保存：'+d.path;toast('已导出全部车面与参考线');});
  $('extract-textures').onclick=run(async()=>{if(!ready)throw Error('请等待 3D 模型载入');$('extract-textures').disabled=true;toast('正在提取原始 UV 与材质通道…');try{const files=await bridge().extract();const d=await api('export',{name:project.name+'_UV与材质.zip',files});toast('UV 与车漆贴图已提取\n'+d.path);}finally{$('extract-textures').disabled=false;}});
  $('screenshot').onclick=run(async()=>{if(!ready)throw Error('请等待模型载入');await sync();await new Promise(r=>setTimeout(r,160));await exportFile(project.name+'_3D预览.png',await bridge().screenshot(),true);});
  $('high-res-render').onclick=()=>{if(!ready){toast('请等待模型载入',true);return;}$('render-result').hidden=true;$('render-status').textContent='输入角度和输出尺寸后开始渲染';$('high-res-dialog').showModal();};
  $('render-start').onclick=run(async()=>{if(!ready)throw Error('请等待模型载入');const yaw=Number($('render-yaw').value),pitch=Number($('render-pitch').value),fov=Number($('render-fov').value),currentView=$('render-current').checked,width=Number($('render-width').value),height=Number($('render-height').value);if(![width,height].every(Number.isInteger)||width<512||height<512||width*height>16000000||!currentView&&(![yaw,pitch,fov].every(Number.isFinite)||yaw< -180||yaw>180||pitch< -10||pitch>90||fov<15||fov>90))throw Error('角度、FOV 或尺寸超出有效范围；FOV 为 15–90°，输出至少 512 px，像素总量不超过 16 MP');const button=$('render-start');button.disabled=true;$('render-status').textContent='正在离屏渲染…';try{await sync();const image=await bridge().renderOffscreen({yaw,pitch,fov,width,height,currentView});$('render-image').src=image;$('render-dimensions').textContent=`${width} × ${height} px · ${currentView?'当前构图':yaw+'° / '+pitch+'° · FOV '+fov+'°'}`;$('render-result').hidden=false;$('render-status').textContent='渲染完成';}finally{button.disabled=false;}});
  $('render-download').onclick=run(async()=>{const image=$('render-image').src;if(!image.startsWith('data:image/png'))throw Error('请先完成渲染');await exportFile(project.name+`_离屏渲染_${$('render-width').value}x${$('render-height').value}.png`,image,true);});
  window.addEventListener('keydown',e=>{if(!drag)return;if(e.key==='Escape'||(e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();e.stopImmediatePropagation();finishDrag(true);}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s')finishDrag();},true);
  window.addEventListener('keydown',e=>{const editing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();run(()=>save())();return;}if(editing||document.querySelector('dialog[open]'))return;if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(e.key.toLowerCase()==='y'){e.preventDefault();redo();}if(e.key.toLowerCase()==='d'){e.preventDefault();duplicate();}}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}else if(e.key==='Escape'){selected=null;updateArtworkPicking();render();renderLayers();renderProperties();}else if(layer()&&!layer().wrap&&!layer().locked&&e.key.startsWith('Arrow')){e.preventDefault();remember();const n=e.shiftKey?10:1;if(e.key==='ArrowLeft')layer().x-=n;if(e.key==='ArrowRight')layer().x+=n;if(e.key==='ArrowUp')layer().y-=n;if(e.key==='ArrowDown')layer().y+=n;changed();}});
  window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
  window.studio={get project(){return project;},get surface(){return surface;},get activePart(){return activePart;},get paintData(){return paintData;},get texturePrecision(){return lastTexturePrecision;},get allLayers(){return allLayers();},get stage(){return stage;},get ready(){return ready&&!initializing;},get selected(){return selected;},get bridge(){return bridge();},get settings(){return settings;},get guides(){return guideCache;},addImage,dropOnPaint,openProject,sync,save,setSurface,setPart,createPanel,printSVG,printRaster,importPaths,importFiles,addAssetLayer};
  refresh();setLayout(settings.layout);updateMemory();setInterval(updateMemory,5000);
  setInterval(()=>{if(ready&&!initializing&&project.paintMode==='factory'){const color=bridge()?.info.factoryColor;if(color&&project.factoryColor!=='#'+color){project.factoryColor='#'+color;refresh();}}},500);
  paintDataReady=fetch('/__studio/paint-surfaces.json').then(r=>r.ok?r.json():null).then(data=>{if(data)loadPaintData(data);}).catch(()=>{});
  const lastProject=localStorage.getItem('su7-last-project');if(lastProject){$('home-resume').hidden=false;$('home-resume').onclick=run(async()=>{const d=await api('open',{file:lastProject});await openProject(d.project);});}
